mapper.select:
SELECT ph.user_no, u.user_nm, ph.user_id, DATE_FORMAT(mission_date, '%Y-%m') AS mission_month, -- 예: '2026-09' COUNT(CASE WHEN category = 'WORK' THEN amount END) AS work_count, SUM(CASE WHEN category = 'WORK' THEN amount ELSE 0 END) AS work_amount, SUM(CASE WHEN category = 'REFERRAL' THEN amount ELSE 0 END) AS referral_amount, SUM(CASE WHEN category = 'FULL_ATTEND' THEN amount ELSE 0 END) AS attend_amount, SUM(CASE WHEN category = 'leader_extra' THEN amount ELSE 0 END) AS leader_amount, SUM(CASE WHEN category = 'OVERPAY' THEN amount ELSE 0 END) AS overpay_amount, SUM(amount) AS total_point FROM point_history ph LEFT OUTER JOIN user u ON ph.user_no = u.id
WHERE mission_date LIKE CONCAT(#{selectedMonth}, '%')
GROUP BY user_id, user_no, mission_month ORDER BY total_point desc LIMIT #{page.index}, #{page.rows}
